17	package org.springframework.boot.json;
18	
19	import java.io.IOException;
20	import java.lang.ref.SoftReference;
21	import java.nio.ByteBuffer;
22	import java.nio.CharBuffer;
23	import java.nio.charset.Charset;
24	import java.nio.charset.CharsetEncoder;
25	import java.nio.charset.CoderResult;
26	import java.nio.charset.CodingErrorAction;
27	
28	import org.jspecify.annotations.Nullable;
29	
30	import org.springframework.util.Assert;
31	
32	/**
33	 * {@link Appendable} implementation that can be used to return a byte array. Designed to
34	 * reduce memory pressure for {@link WritableJson#toByteArray(Charset)} by using a single
35	 * cached buffer scoped to the thread.
36	 *
37	 * @author Phillip Webb
38	 */
39	class AppendableByteArray implements Appendable {
40	
41		private static final ThreadLocal<@Nullable SoftReference<AppendableByteArray>> cache = new ThreadLocal<>();
42	
43		private static final int DEFAULT_INITIAL_SIZE = 8192;
44	
45		private static final int DEFAULT_EXPANSION_SIZE = 8192;
46	
47		private static final byte[] NO_BYTES = {};
48	
49		private final Charset charset;
50	
51		private final CharsetEncoder encoder;
52	
53		private final int expansionSize;
54	
55		private ByteBuffer out;
56	
57		AppendableByteArray(Charset charset) {
58			this(charset, DEFAULT_INITIAL_SIZE, DEFAULT_EXPANSION_SIZE);
59		}
60	
61		AppendableByteArray(Charset charset, int initialSize, int expansionSize) {
62			this.charset = charset;
63			this.encoder = charset.newEncoder()
64				.onMalformedInput(CodingErrorAction.REPLACE)
65				.onUnmappableCharacter(CodingErrorAction.REPLACE);
66			this.out = ByteBuffer.allocate(initialSize);
67			this.expansionSize = expansionSize;
68		}
69	
70		@Override
71		public AppendableByteArray append(@Nullable CharSequence charSequence, int start, int end) throws IOException {
72			return append(((charSequence != null) ? charSequence : "null").subSequence(start, end));
73		}
74	
75		@Override
76		public AppendableByteArray append(CharSequence charSequence) throws IOException {
77			return append(String.valueOf(charSequence).toCharArray());
78		}
79	
80		@Override
81		public AppendableByteArray append(char ch) throws IOException {
82			return append(new char[] { ch });
83		}
84	
85		private AppendableByteArray append(char[] chars) throws IOException {
86			return (chars.length != 0) ? append(CharBuffer.wrap(chars)) : this;
87		}
88	
89		private AppendableByteArray append(CharBuffer in) throws IOException {
90			CoderResult result = this.encoder.encode(in, this.out, false);
91			if (result.isUnderflow()) {
92				return this;
93			}
94			if (result.isOverflow()) {
95				ByteBuffer out = this.out;
96				this.out = ByteBuffer.allocate(out.capacity() + this.expansionSize);
97				out.flip();
98				this.out.put(out);
99				return append(in);
100			}
101			result.throwException();
102			return this;
103		}
104	
105		byte[] toByteArray() {
106			this.out.flip();
107			int limit = this.out.limit();
108			int position = this.out.position();
109			int size = limit - position;
110			if (size <= 0) {
111				return NO_BYTES;
112			}
113			byte[] result = new byte[size];
114			System.arraycopy(this.out.array(), this.out.arrayOffset() + position, result, 0, size);
115			reset();
116			return result;
117		}
118	
119		private void reset() {
120			this.out.clear();
121			this.encoder.reset();
122		}
123	
124		static AppendableByteArray get(Charset charset) {
125			Assert.notNull(charset, "'charset' must not be null");
126			SoftReference<AppendableByteArray> cached = cache.get();
127			AppendableByteArray result = (cached != null) ? cached.get() : null;
128			if (result == null || !result.charset.equals(charset)) {
129				result = new AppendableByteArray(charset);
130				cache.set(new SoftReference<>(result));
131			}
132			return result;
133		}
134	
135	}
