43	/**
44	 * Internal class used by {@link JsonWriter} to handle the lower-level concerns of writing
45	 * JSON.
46	 *
47	 * @author Phillip Webb
48	 * @author Moritz Halbritter
49	 */
50	class JsonValueWriter {
51	
52		private static final int DEFAULT_MAX_NESTING_DEPTH = 500;
53	
54		private final Appendable out;
55	
56		private final int maxNestingDepth;
57	
58		private MemberPath path = MemberPath.ROOT;
59	
60		private final Deque<JsonWriterFiltersAndProcessors> filtersAndProcessors = new ArrayDeque<>();
61	
62		private final Deque<ActiveSeries> activeSeries = new ArrayDeque<>();
63	
64		/**
65		 * Create a new {@link JsonValueWriter} instance.
66		 * @param out the {@link Appendable} used to receive the JSON output
67		 */
68		JsonValueWriter(Appendable out) {
69			this(out, DEFAULT_MAX_NESTING_DEPTH);
70		}
71	
72		/**
73		 * Create a new {@link JsonValueWriter} instance.
74		 * @param out the {@link Appendable} used to receive the JSON output
75		 * @param maxNestingDepth the maximum allowed nesting depth for JSON objects and
76		 * arrays
77		 */
78		JsonValueWriter(Appendable out, int maxNestingDepth) {
79			this.out = out;
80			this.maxNestingDepth = maxNestingDepth;
81		}
82	
83		void pushProcessors(JsonWriterFiltersAndProcessors jsonProcessors) {
84			this.filtersAndProcessors.addLast(jsonProcessors);
85		}
86	
87		void popProcessors() {
88			this.filtersAndProcessors.removeLast();
89		}
90	
91		/**
92		 * Write a name value pair, or just a value if {@code name} is {@code null}.
93		 * @param <N> the name type in the pair
94		 * @param <V> the value type in the pair
95		 * @param name the name of the pair or {@code null} if only the value should be
96		 * written
97		 * @param value the value
98		 */
99		<N, V> void write(@Nullable N name, @Nullable V value) {
100			if (name != null) {
101				writePair(name, value);
102			}
103			else {
104				write(value);
105			}
106		}
107	
108		/**
109		 * Write a value to the JSON output. The following value types are supported:
110		 * <ul>
111		 * <li>Any {@code null} value</li>
112		 * <li>A {@link WritableJson} instance</li>
113		 * <li>Any {@link Iterable} or Array (written as a JSON array)</li>
114		 * <li>A {@link Map} (written as a JSON object)</li>
115		 * <li>Any {@link Number}</li>
116		 * <li>A {@link Boolean}</li>
117		 * </ul>
118		 * All other values are written as JSON strings.
119		 * @param <V> the value type
120		 * @param value the value to write
121		 */
122		<V> void write(@Nullable V value) {
123			value = processValue(value);
124			if (value == null) {
125				append("null");
126			}
127			else if (value instanceof WritableJson writableJson) {
128				try {
129					writableJson.to(this.out);
130				}
131				catch (IOException ex) {
132					throw new UncheckedIOException(ex);
133				}
134			}
135			else if (value instanceof Iterable<?> iterable && canWriteAsArray(iterable)) {
136				writeArray(iterable::forEach);
137			}
138			else if (ObjectUtils.isArray(value)) {
139				writeArray(Arrays.asList(ObjectUtils.toObjectArray(value))::forEach);
140			}
141			else if (value instanceof Map<?, ?> map) {
142				writeObject(map::forEach);
143			}
144			else if (value instanceof Number || value instanceof Boolean) {
145				append(value.toString());
146			}
147			else {
148				writeString(value);
149			}
150		}
151	
152		private boolean canWriteAsArray(Iterable<?> iterable) {
153			return !(iterable instanceof Path);
154		}
155	
156		/**
157		 * Start a new {@link Series} (JSON object or array).
158		 * @param series the series to start
159		 * @see #end(Series)
160		 * @see #writePairs(Consumer)
161		 * @see #writeElements(Consumer)
162		 */
163		void start(@Nullable Series series) {
164			if (series != null) {
165				int nestingDepth = this.activeSeries.size();
166				Assert.state(nestingDepth <= this.maxNestingDepth,
167						() -> "JSON nesting depth (%s) exceeds maximum depth of %s (current path: %s)"
168							.formatted(nestingDepth, this.maxNestingDepth, this.path));
169				this.activeSeries.push(new ActiveSeries(series));
170				append(series.openChar);
171			}
172		}
173	
174		/**
175		 * End an active {@link Series} (JSON object or array).
176		 * @param series the series type being ended (must match {@link #start(Series)})
177		 * @see #start(Series)
178		 */
179		void end(@Nullable Series series) {
180			if (series != null) {
181				this.activeSeries.pop();
182				append(series.closeChar);
183			}
184		}
185	
186		/**
187		 * Write the specified elements to a newly started {@link Series#ARRAY array series}.
188		 * @param <E> the element type
189		 * @param elements a callback that will be used to provide each element. Typically a
190		 * {@code forEach} method reference.
191		 * @see #writeElements(Consumer)
192		 */
193		<E> void writeArray(Consumer<Consumer<E>> elements) {
194			start(Series.ARRAY);
195			elements.accept(ThrowingConsumer.of(this::writeElement));
196			end(Series.ARRAY);
197		}
198	
199		/**
200		 * Write the specified elements to an already started {@link Series#ARRAY array
201		 * series}.
202		 * @param <E> the element type
203		 * @param elements a callback that will be used to provide each element. Typically a
204		 * {@code forEach} method reference.
205		 * @see #writeElements(Consumer)
206		 */
207		<E> void writeElements(Consumer<Consumer<E>> elements) {
208			elements.accept(ThrowingConsumer.of(this::writeElement));
209		}
210	
211		<E> void writeElement(E element) {
212			ActiveSeries activeSeries = this.activeSeries.peek();
213			Assert.state(activeSeries != null, "No series has been started");
214			this.path = activeSeries.updatePath(this.path);
215			activeSeries.incrementIndexAndAddCommaIfRequired();
216			write(element);
217			this.path = activeSeries.restorePath(this.path);
218		}
219	
220		/**
221		 * Write the specified pairs to a newly started {@link Series#OBJECT object series}.
222		 * @param <N> the name type in the pair
223		 * @param <V> the value type in the pair
224		 * @param pairs a callback that will be used to provide each pair. Typically a
225		 * {@code forEach} method reference.
226		 * @see #writePairs(Consumer)
227		 */
228		<N, V> void writeObject(Consumer<BiConsumer<N, V>> pairs) {
229			start(Series.OBJECT);
230			pairs.accept(this::writePair);
231			end(Series.OBJECT);
232		}
233	
234		/**
235		 * Write the specified pairs to an already started {@link Series#OBJECT object
236		 * series}.
237		 * @param <N> the name type in the pair
238		 * @param <V> the value type in the pair
239		 * @param pairs a callback that will be used to provide each pair. Typically a
240		 * {@code forEach} method reference.
241		 * @see #writePairs(Consumer)
242		 */
243		<N, V> void writePairs(Consumer<BiConsumer<N, V>> pairs) {
244			pairs.accept(this::writePair);
245		}
246	
247		private <N, V> void writePair(N name, @Nullable V value) {
248			this.path = this.path.child(name.toString());
249			if (!isFilteredPath()) {
250				String processedName = processName(name.toString());
251				ActiveSeries activeSeries = this.activeSeries.peek();
252				Assert.state(activeSeries != null, "No series has been started");
253				activeSeries.incrementIndexAndAddCommaIfRequired();
254				Assert.state(activeSeries.addName(processedName),
255						() -> "The name '" + processedName + "' has already been written");
256				writeString(processedName);
257				append(":");
258				write(value);
259			}
260			this.path = (this.path.parent() != null) ? this.path.parent() : MemberPath.ROOT;
261		}
262	
263		private void writeString(Object value) {
264			try {
265				this.out.append('"');
266				String string = value.toString();
267				for (int i = 0; i < string.length(); i++) {
268					char ch = string.charAt(i);
269					switch (ch) {
270						case '"' -> this.out.append("\\\"");
271						case '\\' -> this.out.append("\\\\");
272						case '\b' -> this.out.append("\\b");
273						case '\f' -> this.out.append("\\f");
274						case '\n' -> this.out.append("\\n");
275						case '\r' -> this.out.append("\\r");
276						case '\t' -> this.out.append("\\t");
277						default -> {
278							if (Character.isISOControl(ch)) {
279								this.out.append("\\u");
280								this.out.append(String.format("%04X", (int) ch));
281							}
282							else {
283								this.out.append(ch);
284							}
285						}
286					}
287				}
288				this.out.append('"');
289			}
290			catch (IOException ex) {
291				throw new UncheckedIOException(ex);
292			}
293		}
294	
295		private void append(String value) {
296			try {
297				this.out.append(value);
298			}
299			catch (IOException ex) {
300				throw new UncheckedIOException(ex);
301			}
302	
303		}
304	
305		private void append(char ch) {
306			try {
307				this.out.append(ch);
308			}
309			catch (IOException ex) {
310				throw new UncheckedIOException(ex);
311			}
312		}
313	
314		private boolean isFilteredPath() {
315			for (JsonWriterFiltersAndProcessors filtersAndProcessors : this.filtersAndProcessors) {
316				for (Predicate<MemberPath> pathFilter : filtersAndProcessors.pathFilters()) {
317					if (pathFilter.test(this.path)) {
318						return true;
319					}
320				}
321			}
322			return false;
323		}
324	
325		private String processName(String name) {
326			for (JsonWriterFiltersAndProcessors filtersAndProcessors : this.filtersAndProcessors) {
327				for (NameProcessor nameProcessor : filtersAndProcessors.nameProcessors()) {
328					name = processName(name, nameProcessor);
329				}
330			}
331			return name;
332		}
333	
334		private String processName(String name, NameProcessor nameProcessor) {
335			name = nameProcessor.processName(this.path, name);
336			Assert.state(StringUtils.hasLength(name), "NameProcessor " + nameProcessor + " returned an empty result");
337			return name;
338		}
339	
340		private <V> @Nullable V processValue(@Nullable V value) {
341			for (JsonWriterFiltersAndProcessors filtersAndProcessors : this.filtersAndProcessors) {
342				for (ValueProcessor<?> valueProcessor : filtersAndProcessors.valueProcessors()) {
343					value = processValue(value, valueProcessor);
344				}
345			}
346			return value;
347		}
348	
349		// Lambda isn't detected with the correct nullability
350		@SuppressWarnings({ "unchecked", "NullAway" })
351		private <V> @Nullable V processValue(@Nullable V value, ValueProcessor<?> valueProcessor) {
352			return (V) LambdaSafe
353				.callback(ValueProcessor.class, valueProcessor, this.path, new @Nullable Object[] { value })
354				.invokeAnd((call) -> call.processValue(this.path, value))
355				.get(value);
356		}
357	
358		/**
359		 * A series of items that can be written to the JSON output.
360		 */
361		enum Series {
362	
363			/**
364			 * A JSON object series consisting of name/value pairs.
365			 */
366			OBJECT('{', '}'),
367	
368			/**
369			 * A JSON array series consisting of elements.
370			 */
371			ARRAY('[', ']');
372	
373			final char openChar;
374	
375			final char closeChar;
376	
377			Series(char openChar, char closeChar) {
378				this.openChar = openChar;
379				this.closeChar = closeChar;
380			}
381	
382		}
383	
384		/**
385		 * Details of the currently active {@link Series}.
386		 */
387		private final class ActiveSeries {
388	
389			private final Series series;
390	
391			private int index;
392	
393			private final Set<String> names = new HashSet<>();
394	
395			private ActiveSeries(Series series) {
396				this.series = series;
397			}
398	
399			boolean addName(String processedName) {
400				return this.names.add(processedName);
401			}
402	
403			MemberPath updatePath(MemberPath path) {
404				if (this.series != Series.ARRAY) {
405					return path;
406				}
407				return path.child(this.index);
408			}
409	
410			MemberPath restorePath(MemberPath path) {
411				if (this.series != Series.ARRAY) {
412					return path;
413				}
414				return (path.parent() != null) ? path.parent() : MemberPath.ROOT;
415			}
416	
417			void incrementIndexAndAddCommaIfRequired() {
418				if (this.index > 0) {
419					append(',');
420				}
421				this.index++;
422			}
423	
424		}
425	
426	}
